// WF4 runtime configuration. NON-SECRET values only.
// The database credential is selected on the Postgres node, never written here.
const config = {
  thresholdDays: 7,                                  // the specification's overdue threshold
  reportUrl:     'https://postman-echo.com/post',    // stub for SendGrid or a Slack webhook
  recipient:     'payments-ops@example.com',
  teamName:      'Payments Operations',
  demoMode: true
};
return $input.all().map(i => ({ json: { ...i.json, config } }));

// Turns query rows into one summary object.
// The Postgres node has alwaysOutputData ON, so an empty result still emits one empty
// item. Filtering on contractor_id is what makes the zero-row case a normal outcome
// rather than a workflow that quietly stops.
const cfg = $('Set Runtime Config').first().json.config;
const rows = $input.all().map(i => i.json).filter(r => r && r.contractor_id);

const today = new Date();
const daysSince = (d) => {
  const then = new Date(String(d).slice(0, 10) + 'T00:00:00Z');
  const now  = new Date(today.toISOString().slice(0, 10) + 'T00:00:00Z');
  return Math.round((now - then) / 86400000);
};

const contractors = rows.map(r => ({
  contractor_id: r.contractor_id,
  name: r.name,
  agency: r.agency,
  last_payment_date: String(r.last_payment_date).slice(0, 10),
  days_overdue: daysSince(r.last_payment_date)
}));

// Grouped by agency, because the person reading this at 08:00 chases one agency at a
// time, not one contractor at a time.
const byAgency = {};
for (const c of contractors) (byAgency[c.agency] = byAgency[c.agency] || []).push(c);
const agencies = Object.keys(byAgency).sort((a, b) => byAgency[b].length - byAgency[a].length);

// Rows arrive ORDER BY last_payment_date ASC, so the oldest is first. Recomputed here
// anyway rather than trusting the ordering to survive a future query edit.
const oldest = contractors.reduce((a, c) => (!a || c.days_overdue > a.days_overdue ? c : a), null);

return [{ json: { config: cfg,
  run_at: today.toISOString(),
  summary: {
    total_count: contractors.length,
    threshold_days: cfg.thresholdDays,
    contractors,
    agencies: agencies.map(a => ({ agency: a, count: byAgency[a].length, contractors: byAgency[a] })),
    oldest
  },
  has_results: contractors.length > 0 } }];

// Human readable. A person reads this at 08:00 with a coffee, not a JSON parser.
const e = $input.first().json, s = e.summary, cfg = e.config;
const tag = cfg.demoMode ? '[DEMO] ' : '';

const when = new Date(e.run_at).toLocaleDateString('en-GB',
  { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/London' });

const L = [];
L.push('Overdue pending payments');
L.push(when);
L.push('');
L.push(s.total_count + ' contractor' + (s.total_count === 1 ? ' has' : 's have') +
       ' been pending for more than ' + s.threshold_days + ' days.');
L.push('');
L.push('Oldest: ' + s.oldest.name + ' (' + s.oldest.agency + '), last paid ' +
       s.oldest.last_payment_date + ', ' + s.oldest.days_overdue + ' days ago.');
L.push('');
L.push('By agency:');
for (const a of s.agencies) {
  L.push('');
  L.push('  ' + a.agency + '  (' + a.count + ')');
  for (const c of a.contractors) {
    L.push('    ' + c.name.padEnd(20) + ' ' + c.contractor_id +
           '   last paid ' + c.last_payment_date + '   ' + c.days_overdue + ' days');
  }
}
L.push('');
L.push('Chase the oldest first. Anything past 30 days should be escalated.');

return [{ json: { ...e, outcome: 'report_sent', reportBody: {
  to: cfg.recipient,
  subject: tag + 'Overdue pending payments: ' + s.total_count + ' contractor' +
           (s.total_count === 1 ? '' : 's') + ' need chasing',
  text: L.join('\n')
} } }];

// Zero results is a normal, successful outcome, not an error and not silence.
// A daily report that simply does not arrive is indistinguishable from a broken workflow,
// which is exactly how an unpaid contractor goes unnoticed for a week.
const e = $input.first().json, cfg = e.config;
const tag = cfg.demoMode ? '[DEMO] ' : '';
const when = new Date(e.run_at).toLocaleDateString('en-GB',
  { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/London' });

const text = [
  'Overdue pending payments',
  when,
  '',
  'Nothing to action today.',
  '',
  'No contractor has been pending for more than ' + cfg.thresholdDays + ' days.',
  'The query ran successfully and returned zero rows.'
].join('\n');

return [{ json: { ...e, outcome: 'nothing_to_action', reportBody: {
  to: cfg.recipient,
  subject: tag + 'Overdue pending payments: nothing to action today',
  text
} } }];

// If the query itself fails, say so loudly. A report that silently does not arrive looks
// exactly like a day with no overdue payments, and that is the failure this whole
// workflow exists to prevent.
const cfg = $('Set Runtime Config').first().json.config;
const r = $input.first().json;
const detail = String((r.error && (r.error.message || r.error.description)) || r.error ||
                      'unknown database error').slice(0, 400);
const now = new Date().toISOString();

return [{ json: { config: cfg, run_at: now, outcome: 'query_failed',
  summary: { total_count: null, threshold_days: cfg.thresholdDays },
  reportBody: {
    to: cfg.recipient,
    subject: (cfg.demoMode ? '[DEMO] ' : '') +
             '[ACTION REQUIRED] Overdue payments report did not run',
    text: [
      'Overdue pending payments',
      new Date(now).toLocaleDateString('en-GB',
        { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/London' }),
      '',
      'THE REPORT DID NOT RUN. Treat today as unchecked, not as clear.',
      '',
      'Database error: ' + detail,
      '',
      'Someone must confirm manually whether any contractor is overdue.'
    ].join('\n')
  } } }];

const r = $input.first().json;

// Recover the outcome from whichever of the three branches produced it.
let ctx = null;
for (const n of ['Build Overdue Report', 'Build Nothing To Action Notice', 'Build Query Failure Alert']) {
  try { const j = $(n).first().json; if (j && j.outcome) { ctx = j; break; } } catch (err) { /* not this branch */ }
}
if (!ctx) ctx = { outcome: 'unknown', summary: {}, run_at: new Date().toISOString() };

const status = Number(r.statusCode || 0);
const transport = Boolean(r.error) || !status;
const sent = !transport && status >= 200 && status < 300;

return [{ json: {
  run_at: ctx.run_at,
  outcome: ctx.outcome,
  overdue_count: ctx.summary ? ctx.summary.total_count : null,
  oldest: ctx.summary && ctx.summary.oldest ? ctx.summary.oldest : null,
  report_sent: sent,
  send_error: sent ? null : (transport
    ? String((r.error && (r.error.message || r.error.description)) || r.error || 'transport failure').slice(0, 200)
    : 'HTTP ' + status),
  recipient: ctx.reportBody ? ctx.reportBody.to : null,
  subject: ctx.reportBody ? ctx.reportBody.subject : null
} }];
